SELECT 
  FROM daily_snapshots
 WHERE user_id = #{userId}
   AND snapshot_date BETWEEN #{from} AND #{to}
 ORDER BY snapshot_date

SELECT 
  FROM daily_snapshots
 WHERE user_id = #{userId}
   AND snapshot_date >= #{from}
 ORDER BY snapshot_date
 LIMIT 1

SELECT 
  FROM daily_snapshots
 WHERE user_id = #{userId}
   AND snapshot_date <= #{to}
 ORDER BY snapshot_date DESC
 LIMIT 1
